/* Browser demonstration only. Photoshop uses lib/photoshop-host.js. */
(function(){
  const sample='data:image/png;base64,';
  async function sampleImage(){const img=new Image();img.src=sample;await new Promise((r,j)=>{img.onload=r;img.onerror=j;});return img;}
  window.CommotDemoHost={
    async readPreview(max){const img=await sampleImage();const s=Math.min(1,max/Math.max(img.width,img.height));const w=Math.round(img.width*s),h=Math.round(img.height*s);const c=document.createElement('canvas');c.width=w;c.height=h;const ctx=c.getContext('2d');ctx.drawImage(img,0,0,w,h);const image={data:new Uint8Array(ctx.getImageData(0,0,w,h).data),width:w,height:h};return {image,source:{id:1,name:'flat-artwork.png',width:1500,height:1500,resolution:300,historyStateID:1},dataUrl:c.toDataURL('image/jpeg',0.95)};},
    async encodePreview(rgba,width,height,background){const c=document.createElement('canvas');c.width=width;c.height=height;const ctx=c.getContext('2d');ctx.putImageData(new ImageData(new Uint8ClampedArray(rgba),width,height),0,0);const out=document.createElement('canvas');out.width=width;out.height=height;const x=out.getContext('2d');x.fillStyle='rgb('+background.join(',')+')';x.fillRect(0,0,width,height);x.drawImage(c,0,0);return out.toDataURL('image/jpeg',0.95);}
  };
})();